---@class UIBambooCheckpointBuffNode   
---@field TxtNumber                     	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field ImgBuff                       	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform             
local UIBambooCheckpointBuffNode = Class("UIBambooCheckpointBuffNode")
function UIBambooCheckpointBuffNode:__init() 
    self._data = nil
    self._cb = nil
end

function UIBambooCheckpointBuffNode:__delete()
    self._data = nil
    self._cb = nil
end

function UIBambooCheckpointBuffNode:Awake()
    SetButtonAction(self.Root.transform:Find("BtnNode"), Bind(self, self.OnClick))
end

function UIBambooCheckpointBuffNode:Start()
end

function UIBambooCheckpointBuffNode:Refresh(data, cb)
    self._ani = self.Root:GetComponent(typeof(Animator))
    if not data then
        return
    end
    self._data = data
    self._cb = cb

    self:FillSelf()
end

function UIBambooCheckpointBuffNode:FillSelf()
    local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(self._data)
    if vo then
        CfUtils.FillImage(self.ImgIcon, vo.photoId)
    end
    --CfUtils.FillImage(self.ImgBuff, nil)
    --CfUtils.FillText(self.TxtNumber, self._data.num)
end

function UIBambooCheckpointBuffNode:PlayAni(name)
    CfUtils.PlayAnimator(self.Root, name)
end

--
function UIBambooCheckpointBuffNode:OnClick()
    if self._cb then
        self._cb()
    end
    self:RefreshSelect(true)
    local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(self._data)
    if vo then
        GameUtils.ShowCommonTipsBoard(self.Root, vo.name, vo.desc)
    end
end

function UIBambooCheckpointBuffNode:RefreshSelect(isTrue)
    if not self._ani then
        return
    end

    local name = isTrue and "Choose" or "Activate"

    local animatorInfo = self._ani:GetCurrentAnimatorStateInfo(0)
    if isNull(animatorInfo) then
        return
    end
    --相同不动
    if animatorInfo:IsName(name) then 
        return
    end
    CfUtils.PlayAnimator(self.Root, name)
end

function UIBambooCheckpointBuffNode:RefreshNormal()
    if not self._ani then
        return
    end

    CfUtils.PlayAnimator(self.Root, "Normal")
end

function UIBambooCheckpointBuffNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBambooCheckpointBuffNode
